Creating a context, directly building on this module's lesson 2 API client and Module 9's authentication concepts:

import { createContext, useContext, useState } from 'react';

const AuthContext = createContext(null);

export function AuthProvider({ children }) {
  const [user, setUser] = useState(null);

  function login(userData, token) {
    setUser(userData);
    setAuthToken(token); // from lesson 2's API client
  }

  function logout() {
    setUser(null);
    setAuthToken(null);
  }

  return (
    <AuthContext.Provider value={{ user, login, logout }}>
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  return useContext(AuthContext);
}

Wrapping the application once, near its root:

function App() {
  return (
    <AuthProvider>
      <Navbar />
      <MainContent />
    </AuthProvider>
  );
}

Using the context from ANY descendant component, at any depth, without any prop drilling at all:

function Navbar() {
  const { user, logout } = useAuth();
  return user ? <button onClick={logout}>Log out, {user.name}</button> : <LoginLink />;
}

