After installing multer (npm install multer), setting up upload handling:

import multer from 'multer';

const upload = multer({
  dest: 'uploads/', // where files are temporarily/permanently stored
  limits: { fileSize: 5 * 1024 * 1024 } // 5MB limit
});

app.post('/api/avatar', upload.single('avatar'), (req, res, next) => {
  if (!req.file) {
    return res.status(400).json({ success: false, error: 'No file uploaded' });
  }

  res.json({
    success: true,
    data: { filename: req.file.filename, size: req.file.size }
  });
});

upload.single('avatar') is itself middleware (Module 7, lesson 8's pattern, applied here specifically), and the string 'avatar' must exactly match the field name the frontend's FormData uses for that file. Sending the corresponding request from React:

async function uploadAvatar(file) {
  const formData = new FormData();
  formData.append('avatar', file); // 'avatar' matches upload.single('avatar') exactly

  const response = await fetch('/api/avatar', {
    method: 'POST',
    body: formData // NOTE: no Content-Type header set manually - the
                     // browser sets the correct multipart boundary automatically
  });
}

