});

app.listen(3000, () => console.log('Full app running on port 3000'));

// NOTE: no cors import, no cors middleware anywhere in this file at all -
// it's genuinely unnecessary here, since the browser loads everything
// (the page itself AND its API calls) from this exact same origin

// server/config/database.js - Module 8's connection setup, isolated
// into its own file rather than inline in app.js
import { MongoClient } from 'mongodb';

export async function connectToDatabase() {
  const client = new MongoClient(process.env.DATABASE_URL);
  await client.connect();
  return client.db('myApp');
}

// server/middleware/requireAuth.js - Module 9 lesson 6's middleware,
// in its own dedicated file rather than duplicated inline per route file
import jwt from 'jsonwebtoken';

export function requireAuth(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ success: false, error: 'Authentication required' });
  }
  try {
    const token = authHeader.split(' ')[1];
    req.userId = jwt.verify(token, process.env.JWT_SECRET).userId;
    next();
  } catch (err) {
    return res.status(401).json({ success: false, error: 'Invalid or expired token' });
  }
}

